  6→
  7→const MIME_TO_EXT: Record<string, string> = {
  8→  "image/jpeg": ".jpg",
  9→  "image/png": ".png",
 10→  "image/gif": ".gif",
 11→  "image/webp": ".webp",
 12→  "image/svg+xml": ".svg",
 13→  "audio/ogg": ".ogg",
 14→  "audio/mpeg": ".mp3",
 15→  "audio/wav": ".wav",
 16→  "audio/webm": ".webm",
 17→  "audio/mp4": ".m4a",
 18→  "video/mp4": ".mp4",
 19→  "video/webm": ".webm",
 20→  "application/pdf": ".pdf",
 21→  "text/plain": ".txt",
 22→};
 23→
 24→const EXT_TO_MIME: Record<string, string> = {
 25→  ".jpg": "image/jpeg",
 26→  ".jpeg": "image/jpeg",
 27→  ".png": "image/png",
 28→  ".gif": "image/gif",
 29→  ".webp": "image/webp",
 30→  ".svg": "image/svg+xml",
 31→  ".ogg": "audio/ogg",
 32→  ".oga": "audio/ogg",
 33→  ".mp3": "audio/mpeg",
 34→  ".wav": "audio/wav",
 35→  ".m4a": "audio/mp4",
 36→  ".mp4": "video/mp4",
 37→  ".pdf": "application/pdf",
 38→  ".txt": "text/plain",
 39→};
 40→
 41→function classifyMime(mimeType: string): Attachment["type"] {
 42→  if (mimeType.startsWith("image/")) return "image";
 43→  if (mimeType.startsWith("audio/")) return "audio";
 44→  return "file";
 45→}
 46→
 47→export class FileService {
 48→  constructor(private baseDir: string) {}
 49→
 50→  async saveFile(
 51→    sessionId: string,
 52→    fileName: string,
 53→    data: Buffer,
 54→    mimeType: string,
 55→  ): Promise<Attachment> {
 56→    const sessionDir = path.join(this.baseDir, sessionId);
 57→    await fs.promises.mkdir(sessionDir, { recursive: true });
 58→
 59→    const safeName = `${Date.now()}-${fileName.replace(/[^a-zA-Z0-9._-]/g, "_")}`;
 60→    const filePath = path.join(sessionDir, safeName);
 61→    await fs.promises.writeFile(filePath, data);
 62→
 63→    return {
 64→      type: classifyMime(mimeType),
 65→      filePath,
 66→      fileName,
 67→      mimeType,
 68→      size: data.length,
 69→    };
 70→  }
 71→
 72→  async resolveFile(filePath: string): Promise<Attachment | null> {
 73→    try {
 74→      const stat = await fs.promises.stat(filePath);
 75→      if (!stat.isFile()) return null;
 76→
 77→      const ext = path.extname(filePath).toLowerCase();
 78→      const mimeType = EXT_TO_MIME[ext] || "application/octet-stream";
 79→
 80→      return {
 81→        type: classifyMime(mimeType),
 82→        filePath,
 83→        fileName: path.basename(filePath),
 84→        mimeType,
 85→        size: stat.size,
 86→      };
 87→    } catch {
 88→      return null;
 89→    }
 90→  }
 91→
 92→  /**
 93→   * Convert OGG Opus audio to WAV format.
 94→   * Telegram voice messages use OGG Opus which many AI agents can't read.
 95→   */
 96→  async convertOggToWav(oggData: Buffer): Promise<Buffer> {
 97→    const decoder = new OggOpusDecoder();
 98→    await decoder.ready;
 99→    try {
100→      const { channelData, sampleRate } = await decoder.decode(new Uint8Array(oggData));
101→      const wavData = wav.encode(channelData, { sampleRate, float: true, bitDepth: 32 });
102→      return Buffer.from(wavData);
103→    } finally {
104→      decoder.free();
105→    }
106→  }
107→
108→  static extensionFromMime(mimeType: string): string {
109→    return MIME_TO_EXT[mimeType] || ".bin";
110→  }
111→}
