  1→import { nanoid } from "nanoid";
  2→import type { AgentInstance } from "./agent-instance.js";
  3→import type { AgentEvent, Attachment, PermissionRequest, SessionStatus } from "./types.js";
  4→import { TypedEmitter } from "./typed-emitter.js";
  5→import { PromptQueue } from "./prompt-queue.js";
  6→import { PermissionGate } from "./permission-gate.js";
  7→import { createChildLogger, createSessionLogger, type Logger } from "./log.js";
  8→const moduleLog = createChildLogger({ module: "session" });
  9→
 10→// Valid state transitions: from → Set<to>
 11→const VALID_TRANSITIONS: Record<SessionStatus, Set<SessionStatus>> = {
 12→  initializing: new Set(["active", "error"]),
 13→  active: new Set(["error", "finished", "cancelled"]),
 14→  error: new Set(["active"]),
 15→  cancelled: new Set(["active"]),
 16→  finished: new Set(),
 17→};
 18→
 19→export interface SessionEvents {
 20→  agent_event: (event: AgentEvent) => void;
 21→  permission_request: (request: PermissionRequest) => void;
 22→  session_end: (reason: string) => void;
 23→  status_change: (from: SessionStatus, to: SessionStatus) => void;
 24→  named: (name: string) => void;
 25→  error: (error: Error) => void;
 26→}
 27→
 28→export class Session extends TypedEmitter<SessionEvents> {
 29→  id: string;
 30→  channelId: string;
 31→  threadId: string = "";
 32→  agentName: string;
 33→  workingDirectory: string;
 34→  agentInstance: AgentInstance;
 35→  agentSessionId: string = "";
 36→  private _status: SessionStatus = "initializing";
 37→  name?: string;
 38→  createdAt: Date = new Date();
 39→  dangerousMode: boolean = false;
 40→  log: Logger;
 41→
 42→  readonly permissionGate = new PermissionGate();
 43→  private readonly queue: PromptQueue;
 44→
 45→  constructor(opts: {
 46→    id?: string;
 47→    channelId: string;
 48→    agentName: string;
 49→    workingDirectory: string;
 50→    agentInstance: AgentInstance;
 51→  }) {
 52→    super();
 53→    this.id = opts.id || nanoid(12);
 54→    this.channelId = opts.channelId;
 55→    this.agentName = opts.agentName;
 56→    this.workingDirectory = opts.workingDirectory;
 57→    this.agentInstance = opts.agentInstance;
 58→    this.log = createSessionLogger(this.id, moduleLog);
 59→    this.log.info({ agentName: this.agentName }, "Session created");
 60→
 61→    this.queue = new PromptQueue(
 62→      (text, attachments) => this.processPrompt(text, attachments),
 63→      (err) => {
 64→        this.fail("Prompt execution failed");
 65→        this.log.error({ err }, "Prompt execution failed");
 66→      },
 67→    );
 68→  }
 69→
 70→  // --- State Machine ---
 71→
 72→  get status(): SessionStatus {
 73→    return this._status;
 74→  }
 75→
 76→
 77→  /** Transition to active — from initializing, error, or cancelled */
 78→  activate(): void {
 79→    this.transition("active");
 80→  }
 81→
 82→  /** Transition to error — from initializing or active */
 83→  fail(reason: string): void {
 84→    this.transition("error");
 85→    this.emit("error", new Error(reason));
 86→  }
 87→
 88→  /** Transition to finished — from active only. Emits session_end for backward compat. */
 89→  finish(reason?: string): void {
 90→    this.transition("finished");
 91→    this.emit("session_end", reason ?? "completed");
 92→  }
 93→
 94→  /** Transition to cancelled — from active only (terminal session cancel) */
 95→  markCancelled(): void {
 96→    this.transition("cancelled");
 97→  }
 98→
 99→  private transition(to: SessionStatus): void {
100→    const from = this._status;
101→    const allowed = VALID_TRANSITIONS[from];
102→    if (!allowed?.has(to)) {
103→      throw new Error(
104→        `Invalid session transition: ${from} → ${to}`,
105→      );
106→    }
107→    this._status = to;
108→    this.log.debug({ from, to }, "Session status transition");
109→    this.emit("status_change", from, to);
110→  }
111→
112→  /** Number of prompts waiting in queue */
113→  get queueDepth(): number {
114→    return this.queue.pending;
115→  }
116→
117→  get promptRunning(): boolean {
118→    return this.queue.isProcessing;
119→  }
120→
121→  // --- Public API ---
122→
123→  async enqueuePrompt(text: string, attachments?: Attachment[]): Promise<void> {
124→    await this.queue.enqueue(text, attachments);
125→  }
126→
127→  private async processPrompt(text: string, attachments?: Attachment[]): Promise<void> {
128→    // Handle warmup sentinel
129→    if (text === "\x00__warmup__") {
130→      await this.runWarmup();
131→      return;
132→    }
133→
134→    if (this._status === "initializing") {
135→      this.activate();
136→    }
137→    const promptStart = Date.now();
138→    this.log.debug("Prompt execution started");
139→
140→    await this.agentInstance.prompt(text, attachments);
141→    this.log.info(
142→      { durationMs: Date.now() - promptStart },
143→      "Prompt execution completed",
144→    );
145→
146→    // Auto-name after first user prompt
147→    if (!this.name) {
148→      await this.autoName();
149→    }
150→  }
151→
152→  // NOTE: This injects a summary prompt into the agent's conversation history.
153→  private async autoName(): Promise<void> {
154→    let title = "";
155→
156→    // Intercept at the source — capture text before it reaches the emitter,
157→    // so adapter listeners never see auto-name output.
158→    const originalHandler = this.agentInstance.onSessionUpdate;
159→    this.agentInstance.onSessionUpdate = (event: AgentEvent) => {
160→      if (event.type === "text") title += event.content;
161→      // Swallow all events from auto-name prompt
162→    };
163→
164→    try {
165→      await this.agentInstance.prompt(
166→        "Summarize this conversation in max 5 words for a topic title. Reply ONLY with the title, nothing else.",
167→      );
168→      this.name = title.trim().slice(0, 50) || `Session ${this.id.slice(0, 6)}`;
169→      this.log.info({ name: this.name }, "Session auto-named");
170→
171→      // Emit named event — SessionBridge listens to rename the thread
172→      this.emit("named", this.name);
173→    } catch {
174→      this.name = `Session ${this.id.slice(0, 6)}`;
175→    } finally {
176→      this.agentInstance.onSessionUpdate = originalHandler;
177→    }
178→  }
179→
180→  /** Fire-and-forget warm-up: primes model cache while user types their first message */
181→  async warmup(): Promise<void> {
182→    // Route through PromptQueue to prevent concurrent prompt execution.
183→    // Any user prompts arriving during warmup will be queued and drained after.
184→    await this.queue.enqueue("\x00__warmup__");
185→  }
186→
187→  private async runWarmup(): Promise<void> {
188→    // Pause events but let commands_update pass through
189→    this.pause((_event, args) => {
190→      const agentEvent = args[0] as AgentEvent;
191→      return agentEvent?.type === "commands_update";
192→    });
193→
194→    try {
195→      const start = Date.now();
196→      await this.agentInstance.prompt('Reply with only "ready".');
197→      this.activate();
198→      this.log.info({ durationMs: Date.now() - start }, "Warm-up complete");
199→    } catch (err) {
200→      this.log.error({ err }, "Warm-up failed");
201→    } finally {
202→      this.clearBuffer();
203→      this.resume();
204→    }
205→  }
206→
207→  /** Cancel the current prompt and clear the queue. Stays in active state. */
208→  async abortPrompt(): Promise<void> {
209→    this.queue.clear();
210→    this.log.info("Prompt aborted");
211→    await this.agentInstance.cancel();
212→  }
213→
214→  async destroy(): Promise<void> {
215→    this.log.info("Session destroyed");
216→    await this.agentInstance.destroy();
217→  }
218→}
