103→export class AgentInstance {
104→  private connection!: ClientSideConnection;
105→  private child!: ChildProcess;
106→  private stderrCapture!: StderrCapture;
107→  private terminals: Map<string, TerminalState> = new Map();
108→
109→  sessionId!: string;
110→  agentName: string;
111→  promptCapabilities?: { image?: boolean; audio?: boolean };
112→
113→  // Callbacks — set by core when wiring events
114→  onSessionUpdate: (event: AgentEvent) => void = () => {};
115→  onPermissionRequest: (request: PermissionRequest) => Promise<string> =
116→    async () => "";
117→
118→  private constructor(agentName: string) {
119→    this.agentName = agentName;
120→  }
121→
122→  private static async spawnSubprocess(
123→    agentDef: AgentDefinition,
124→    workingDirectory: string,
125→  ): Promise<AgentInstance> {
126→    const instance = new AgentInstance(agentDef.name);
127→    const resolved = resolveAgentCommand(agentDef.command);
128→    log.debug(
129→      {
130→        agentName: agentDef.name,
131→        command: resolved.command,
132→        args: resolved.args,
133→      },
134→      "Resolved agent command",
135→    );
136→
137→    instance.child = spawn(
138→      resolved.command,
139→      [...resolved.args, ...agentDef.args],
140→      {
141→        stdio: ["pipe", "pipe", "pipe"],
142→        cwd: workingDirectory,
143→        env: { ...process.env, ...agentDef.env },
144→      },
145→    );
146→
147→    await new Promise<void>((resolve, reject) => {
148→      instance.child.on("error", (err) => {
149→        reject(
150→          new Error(
151→            `Failed to spawn agent "${agentDef.name}": ${err.message}. Is "${agentDef.command}" installed?`,
152→          ),
153→        );
154→      });
155→      instance.child.on("spawn", () => resolve());
156→    });
157→
158→    instance.stderrCapture = new StderrCapture(50);
159→    instance.child.stderr!.on("data", (chunk: Buffer) => {
160→      instance.stderrCapture.append(chunk.toString());
161→    });
162→
163→    const stdinLogger = new Transform({
164→      transform(chunk, _enc, cb) {
165→        log.debug(
166→          { direction: "send", raw: chunk.toString().trimEnd() },
167→          "ACP raw",
168→        );
169→        cb(null, chunk);
170→      },
171→    });
172→    stdinLogger.pipe(instance.child.stdin!);
173→
174→    const stdoutLogger = new Transform({
175→      transform(chunk, _enc, cb) {
176→        log.debug(
177→          { direction: "recv", raw: chunk.toString().trimEnd() },
178→          "ACP raw",
179→        );
180→        cb(null, chunk);
181→      },
182→    });
183→    instance.child.stdout!.pipe(stdoutLogger);
184→
185→    const toAgent = nodeToWebWritable(stdinLogger);
186→    const fromAgent = nodeToWebReadable(stdoutLogger);
187→    const stream = ndJsonStream(toAgent, fromAgent);
188→
189→    instance.connection = new ClientSideConnection(
190→      (_agent: Agent): Client => instance.createClient(_agent),
191→      stream,
192→    );
193→
194→    const initResponse = await instance.connection.initialize({
195→      protocolVersion: 1,
196→      clientCapabilities: {
197→        fs: { readTextFile: true, writeTextFile: true },
198→        terminal: true,
199→      },
200→    });
201→    instance.promptCapabilities =
202→      initResponse.agentCapabilities?.promptCapabilities;
203→
204→    log.info(
205→      { promptCapabilities: instance.promptCapabilities ?? {} },
206→      "Agent prompt capabilities",
207→    );
208→
209→    return instance;
210→  }
211→
212→  private setupCrashDetection(): void {
213→    this.child.on("exit", (code, signal) => {
214→      log.info(
215→        { sessionId: this.sessionId, exitCode: code, signal },
216→        "Agent process exited",
217→      );
218→      if (code !== 0 && code !== null) {
219→        const stderr = this.stderrCapture.getLastLines();
220→        this.onSessionUpdate({
221→          type: "error",
222→          message: `Agent crashed (exit code ${code})\n${stderr}`,
223→        });
224→      }
225→    });
226→
227→    this.connection.closed.then(() => {
228→      log.debug({ sessionId: this.sessionId }, "ACP connection closed");
229→    });
230→  }
231→
232→  static async spawn(
233→    agentDef: AgentDefinition,
234→    workingDirectory: string,
235→  ): Promise<AgentInstance> {
236→    log.debug(
237→      { agentName: agentDef.name, command: agentDef.command },
238→      "Spawning agent",
239→    );
240→    const spawnStart = Date.now();
241→
242→    const instance = await AgentInstance.spawnSubprocess(
243→      agentDef,
244→      workingDirectory,
245→    );
246→
247→    const response = await instance.connection.newSession({
248→      cwd: workingDirectory,
249→      mcpServers: [],
250→    });
251→    instance.sessionId = response.sessionId;
252→    instance.setupCrashDetection();
253→
254→    log.info(
255→      { sessionId: response.sessionId, durationMs: Date.now() - spawnStart },
256→      "Agent spawn complete",
257→    );
258→    return instance;
259→  }
260→
261→  static async resume(
262→    agentDef: AgentDefinition,
263→    workingDirectory: string,
264→    agentSessionId: string,
265→  ): Promise<AgentInstance> {
266→    log.debug({ agentName: agentDef.name, agentSessionId }, "Resuming agent");
267→    const spawnStart = Date.now();
268→
269→    const instance = await AgentInstance.spawnSubprocess(
270→      agentDef,
271→      workingDirectory,
272→    );
273→
274→    try {
275→      const response = await instance.connection.unstable_resumeSession({
276→        sessionId: agentSessionId,
277→        cwd: workingDirectory,
278→      });
279→      instance.sessionId = response.sessionId;
280→      log.info(
281→        { sessionId: response.sessionId, durationMs: Date.now() - spawnStart },
282→        "Agent resume complete",
283→      );
284→    } catch (err) {
285→      log.warn(
286→        { err, agentSessionId },
287→        "Resume failed, falling back to new session",
288→      );
289→      const response = await instance.connection.newSession({
290→        cwd: workingDirectory,
291→        mcpServers: [],
292→      });
293→      instance.sessionId = response.sessionId;
294→      log.info(
295→        { sessionId: response.sessionId, durationMs: Date.now() - spawnStart },
296→        "Agent fallback spawn complete",
297→      );
298→    }
299→
300→    instance.setupCrashDetection();
301→    return instance;
302→  }
303→
304→  // createClient — implemented in Task 6b
305→  private createClient(_agent: Agent): Client {
306→    const self = this;
307→    const MAX_OUTPUT_BYTES = 1024 * 1024; // 1MB cap
308→
309→    return {
310→      // ── Session updates ──────────────────────────────────────────────────
311→      async sessionUpdate(params) {
312→        const update = params.update;
313→        let event: AgentEvent | null = null;
314→
315→        switch (update.sessionUpdate) {
316→          case "agent_message_chunk":
317→            if (update.content.type === "text") {
318→              event = { type: "text", content: update.content.text };
319→            } else if (update.content.type === "image") {
320→              const c = update.content as unknown as { data: string; mimeType: string };
321→              event = { type: "image_content", data: c.data, mimeType: c.mimeType };
322→            } else if (update.content.type === "audio") {
323→              const c = update.content as unknown as { data: string; mimeType: string };
324→              event = { type: "audio_content", data: c.data, mimeType: c.mimeType };
325→            }
326→            break;
327→          case "agent_thought_chunk":
328→            if (update.content.type === "text") {
329→              event = { type: "thought", content: update.content.text };
330→            }
331→            break;
332→          case "tool_call":
333→            event = {
334→              type: "tool_call",
335→              id: update.toolCallId,
336→              name: update.title,
337→              kind: update.kind ?? undefined,
338→              status: update.status ?? "pending",
339→              content: update.content ?? undefined,
340→              rawInput: (update as any).rawInput ?? undefined,
341→              meta: (update as any)._meta ?? undefined,
342→            };
343→            break;
344→          case "tool_call_update":
345→            event = {
346→              type: "tool_update",
347→              id: update.toolCallId,
348→              name: update.title ?? undefined,
349→              kind: update.kind ?? undefined,
350→              status: update.status ?? "pending",
351→              content: update.content ?? undefined,
352→              rawInput: (update as any).rawInput ?? undefined,
353→              meta: (update as any)._meta ?? undefined,
354→            };
355→            break;
356→          case "plan":
357→            event = { type: "plan", entries: update.entries };
358→            break;
359→          case "usage_update":
360→            event = {
361→              type: "usage",
362→              tokensUsed: update.used,
363→              contextSize: update.size,
364→              cost: update.cost ?? undefined,
365→            };
366→            break;
367→          case "available_commands_update":
368→            event = {
369→              type: "commands_update",
370→              commands: update.availableCommands,
371→            };
372→            break;
373→          default:
374→            // Unknown update type — ignore
375→            return;
376→        }
377→
378→        if (event !== null) {
379→          self.onSessionUpdate(event);
380→        }
381→      },
382→
383→      // ── Permission requests ──────────────────────────────────────────────
384→      async requestPermission(params) {
385→        const permissionRequest: PermissionRequest = {
386→          id: params.toolCall.toolCallId,
387→          description: params.toolCall.title ?? params.toolCall.toolCallId,
388→          options: params.options.map((opt: SdkPermissionOption) => ({
389→            id: opt.optionId,
390→            label: opt.name,
391→            isAllow: opt.kind === "allow_once" || opt.kind === "allow_always",
392→          })),
393→        };
394→
395→        const selectedOptionId =
396→          await self.onPermissionRequest(permissionRequest);
397→        return {
398→          outcome: { outcome: "selected" as const, optionId: selectedOptionId },
399→        };
400→      },
401→
402→      // ── File operations ──────────────────────────────────────────────────
403→      async readTextFile(params) {
404→        const content = await fs.promises.readFile(params.path, "utf-8");
405→        return { content };
406→      },
407→
408→      async writeTextFile(params) {
409→        await fs.promises.mkdir(path.dirname(params.path), { recursive: true });
410→        await fs.promises.writeFile(params.path, params.content, "utf-8");
411→        return {};
412→      },
413→
414→      // ── Terminal operations ──────────────────────────────────────────────
415→      async createTerminal(params) {
416→        const terminalId = randomUUID();
417→        const args = params.args ?? [];
418→        const env: Record<string, string> = {};
419→        for (const ev of params.env ?? []) {
420→          env[ev.name] = ev.value;
421→        }
422→
423→        const childProcess = spawn(params.command, args, {
424→          cwd: params.cwd ?? undefined,
425→          env: { ...process.env, ...env },
426→          shell: false,
427→        });
428→
429→        const state: TerminalState = {
430→          process: childProcess,
431→          output: "",
432→          exitStatus: null,
433→        };
434→        self.terminals.set(terminalId, state);
435→
436→        const outputByteLimit = params.outputByteLimit ?? MAX_OUTPUT_BYTES;
437→
438→        const appendOutput = (chunk: string) => {
439→          state.output += chunk;
440→          // Truncate from the beginning if over limit
441→          const bytes = Buffer.byteLength(state.output, "utf-8");
442→          if (bytes > outputByteLimit) {
443→            // Find truncation point at character boundary
444→            const excess = bytes - outputByteLimit;
445→            state.output = state.output.slice(excess);
446→          }
447→        };
448→
449→        childProcess.stdout?.on("data", (chunk: Buffer) =>
450→          appendOutput(chunk.toString()),
451→        );
452→        childProcess.stderr?.on("data", (chunk: Buffer) =>
453→          appendOutput(chunk.toString()),
454→        );
455→
456→        childProcess.on("exit", (code, signal) => {
457→          state.exitStatus = { exitCode: code, signal };
458→        });
459→
460→        return { terminalId };
461→      },
462→
463→      async terminalOutput(params) {
464→        const state = self.terminals.get(params.terminalId);
465→        if (!state) {
466→          throw new Error(`Terminal not found: ${params.terminalId}`);
467→        }
468→        return {
469→          output: state.output,
470→          truncated: false,
471→          exitStatus: state.exitStatus
472→            ? {
473→                exitCode: state.exitStatus.exitCode,
474→                signal: state.exitStatus.signal,
475→              }
476→            : undefined,
477→        };
478→      },
479→
480→      async waitForTerminalExit(params) {
481→        const state = self.terminals.get(params.terminalId);
482→        if (!state) {
483→          throw new Error(`Terminal not found: ${params.terminalId}`);
484→        }
485→        if (state.exitStatus !== null) {
486→          return {
487→            exitCode: state.exitStatus.exitCode,
488→            signal: state.exitStatus.signal,
489→          };
490→        }
491→        return new Promise((resolve) => {
492→          state.process.on("exit", (code, signal) => {
493→            resolve({ exitCode: code, signal });
494→          });
495→        });
496→      },
497→
498→      async killTerminal(params) {
499→        const state = self.terminals.get(params.terminalId);
500→        if (!state) {
501→          throw new Error(`Terminal not found: ${params.terminalId}`);
502→        }
503→        state.process.kill("SIGTERM");
504→        return {};
505→      },
506→
507→      async releaseTerminal(params) {
508→        const state = self.terminals.get(params.terminalId);
509→        if (!state) {
510→          return;
511→        }
512→        state.process.kill("SIGKILL");
513→        self.terminals.delete(params.terminalId);
514→      },
515→    };
516→  }
517→
518→  async prompt(text: string, attachments?: Attachment[]): Promise<PromptResponse> {
519→    const contentBlocks: Array<Record<string, unknown>> = [{ type: "text", text }];
520→
521→    for (const att of attachments ?? []) {
522→      const tooLarge = att.size > 10 * 1024 * 1024; // 10MB base64 guard
523→
524→      if (att.type === "image" && this.promptCapabilities?.image && !tooLarge) {
525→        const data = await fs.promises.readFile(att.filePath);
526→        contentBlocks.push({ type: "image", data: data.toString("base64"), mimeType: att.mimeType });
527→      } else if (att.type === "audio" && this.promptCapabilities?.audio && !tooLarge) {
528→        const data = await fs.promises.readFile(att.filePath);
529→        contentBlocks.push({ type: "audio", data: data.toString("base64"), mimeType: att.mimeType });
530→      } else {
531→        // Fallback: append file path to text so agent can read from disk
532→        if ((att.type === "image" || att.type === "audio") && !tooLarge) {
533→          log.debug(
534→            { type: att.type, capabilities: this.promptCapabilities ?? {} },
535→            "Agent does not support %s content, falling back to file path",
536→            att.type,
537→          );
538→        }
539→        (contentBlocks[0] as { text: string }).text += `\n\n[Attached file: ${att.filePath}]`;
540→      }
541→    }
542→
543→    return this.connection.prompt({
544→      sessionId: this.sessionId,
545→      prompt: contentBlocks as any,
546→    });
547→  }
548→
549→  async cancel(): Promise<void> {
550→    await this.connection.cancel({ sessionId: this.sessionId });
551→  }
552→
553→  async destroy(): Promise<void> {
554→    // Cleanup terminals
555→    for (const [, t] of this.terminals) {
556→      t.process.kill("SIGKILL");
557→    }
558→    this.terminals.clear();
559→
560→    // Kill agent subprocess
561→    this.child.kill("SIGTERM");
562→    setTimeout(() => {
563→      if (!this.child.killed) this.child.kill("SIGKILL");
564→    }, 10_000);
565→  }
566→}
