 19→export class SessionBridge {
 20→  private connected = false;
 21→  private agentEventHandler?: (event: AgentEvent) => void;
 22→  private statusChangeHandler?: (from: SessionStatus, to: SessionStatus) => void;
 23→  private namedHandler?: (name: string) => void;
 24→
 25→  constructor(
 26→    private session: Session,
 27→    private adapter: ChannelAdapter,
 28→    private deps: BridgeDeps,
 29→  ) {}
 30→
 31→  connect(): void {
 32→    if (this.connected) return;
 33→    this.connected = true;
 34→
 35→    this.wireAgentToSession();
 36→    this.wireSessionToAdapter();
 37→    this.wirePermissions();
 38→    this.wireLifecycle();
 39→  }
 40→
 41→  disconnect(): void {
 42→    if (!this.connected) return;
 43→    this.connected = false;
 44→
 45→    if (this.agentEventHandler) {
 46→      this.session.off("agent_event", this.agentEventHandler);
 47→    }
 48→    if (this.statusChangeHandler) {
 49→      this.session.off("status_change", this.statusChangeHandler);
 50→    }
 51→    if (this.namedHandler) {
 52→      this.session.off("named", this.namedHandler);
 53→    }
 54→
 55→    // Reset agent callbacks to no-op
 56→    this.session.agentInstance.onSessionUpdate = () => {};
 57→    this.session.agentInstance.onPermissionRequest = async () => "";
 58→  }
 59→
 60→  private wireAgentToSession(): void {
 61→    this.session.agentInstance.onSessionUpdate = (event: AgentEvent) => {
 62→      this.session.emit("agent_event", event);
 63→    };
 64→  }
 65→
 66→  private wireSessionToAdapter(): void {
 67→    const session = this.session;
 68→    const ctx = {
 69→      get id() { return session.id; },
 70→      get workingDirectory() { return session.workingDirectory; },
 71→    };
 72→
 73→    this.agentEventHandler = (event: AgentEvent) => {
 74→      switch (event.type) {
 75→        case "text":
 76→        case "thought":
 77→        case "tool_call":
 78→        case "tool_update":
 79→        case "plan":
 80→        case "usage":
 81→          this.adapter.sendMessage(
 82→            this.session.id,
 83→            this.deps.messageTransformer.transform(event, ctx),
 84→          );
 85→          break;
 86→
 87→        case "session_end":
 88→          this.session.finish(event.reason);
 89→          this.adapter.cleanupSkillCommands(this.session.id);
 90→          this.adapter.sendMessage(
 91→            this.session.id,
 92→            this.deps.messageTransformer.transform(event),
 93→          );
 94→          this.deps.notificationManager.notify(this.session.channelId, {
 95→            sessionId: this.session.id,
 96→            sessionName: this.session.name,
 97→            type: "completed",
 98→            summary: `Session "${this.session.name || this.session.id}" completed`,
 99→          });
100→          break;
101→
102→        case "error":
103→          this.session.fail(event.message);
104→          this.adapter.cleanupSkillCommands(this.session.id);
105→          this.adapter.sendMessage(
106→            this.session.id,
107→            this.deps.messageTransformer.transform(event),
108→          );
109→          this.deps.notificationManager.notify(this.session.channelId, {
110→            sessionId: this.session.id,
111→            sessionName: this.session.name,
112→            type: "error",
113→            summary: event.message,
114→          });
115→          break;
116→
117→        case "image_content": {
118→          if (this.deps.fileService) {
119→            const fs = this.deps.fileService;
120→            const sid = this.session.id;
121→            const { data, mimeType } = event;
122→            const buffer = Buffer.from(data, "base64");
123→            const ext = FileService.extensionFromMime(mimeType);
124→            fs.saveFile(sid, `agent-image${ext}`, buffer, mimeType).then((att) => {
125→              this.adapter.sendMessage(sid, { type: "attachment", text: "", attachment: att });
126→            }).catch((err) => log.error({ err }, "Failed to save agent image"));
127→          }
128→          break;
129→        }
130→        case "audio_content": {
131→          if (this.deps.fileService) {
132→            const fs = this.deps.fileService;
133→            const sid = this.session.id;
134→            const { data, mimeType } = event;
135→            const buffer = Buffer.from(data, "base64");
136→            const ext = FileService.extensionFromMime(mimeType);
137→            fs.saveFile(sid, `agent-audio${ext}`, buffer, mimeType).then((att) => {
138→              this.adapter.sendMessage(sid, { type: "attachment", text: "", attachment: att });
139→            }).catch((err) => log.error({ err }, "Failed to save agent audio"));
140→          }
141→          break;
142→        }
143→
144→        case "commands_update":
145→          log.debug({ commands: event.commands }, "Commands available");
146→          this.adapter.sendSkillCommands(this.session.id, event.commands);
147→          break;
148→      }
149→    };
150→
151→    this.session.on("agent_event", this.agentEventHandler);
152→  }
153→
154→  private wirePermissions(): void {
155→    this.session.agentInstance.onPermissionRequest = async (
156→      request: PermissionRequest,
157→    ) => {
158→      this.session.emit("permission_request", request);
159→
160→      // Set pending BEFORE sending UI to avoid race condition
161→      const promise = this.session.permissionGate.setPending(request);
162→
163→      // Send permission UI to session topic
164→      await this.adapter.sendPermissionRequest(this.session.id, request);
165→
166→      // Wait for user response — adapter resolves this promise
167→      return promise;
168→    };
169→  }
170→
171→  private wireLifecycle(): void {
172→    // Persist status changes and auto-disconnect on terminal states
173→    this.statusChangeHandler = (from: SessionStatus, to: SessionStatus) => {
174→      this.deps.sessionManager.patchRecord(this.session.id, {
175→        status: to,
176→        lastActiveAt: new Date().toISOString(),
177→      });
178→
179→      // Auto-disconnect on terminal states
180→      if (to === "finished" || to === "cancelled") {
181→        // Disconnect on next tick so current event handlers can complete
182→        queueMicrotask(() => this.disconnect());
183→      }
184→    };
185→    this.session.on("status_change", this.statusChangeHandler);
186→
187→    // Persist and relay name changes
188→    this.namedHandler = (name: string) => {
189→      this.deps.sessionManager.patchRecord(this.session.id, { name });
190→      this.adapter.renameSessionThread(this.session.id, name);
191→    };
192→    this.session.on("named", this.namedHandler);
193→  }
194→}
