   484→  // --- ChannelAdapter implementations ---
   485→
   486→  async sendMessage(
   487→    sessionId: string,
   488→    content: OutgoingMessage,
   489→  ): Promise<void> {
   490→    // Suppress assistant messages during system prompt
   491→    if (this.assistantInitializing && sessionId === this.assistantSession?.id) return;
   492→
   493→    const session = this.core.sessionManager.getSession(sessionId);
   494→    if (!session) return;
   495→    const threadId = Number(session.threadId);
   496→    if (!threadId || isNaN(threadId)) {
   497→      log.warn({ sessionId, threadId: session.threadId }, "Session has no valid threadId, skipping message");
   498→      return;
   499→    }
   500→
   501→    switch (content.type) {
   502→      case "thought": {
   503→        const tracker = this.getOrCreateTracker(sessionId, threadId);
   504→        await tracker.onThought();
   505→        break;
   506→      }
   507→
   508→      case "text": {
   509→        // CRITICAL: This handler must be fully synchronous to preserve text ordering.
   510→        // sendMessage() is not awaited in wireSessionEvents, so multiple text events
   511→        // run concurrently. Any await here creates a gap where subsequent text events
   512→        // process first, causing out-of-order buffer accumulation.
   513→        if (!this.draftManager.hasDraft(sessionId)) {
   514→          const tracker = this.getOrCreateTracker(sessionId, threadId);
   515→          tracker.onTextStart().catch(() => {}); // Fire-and-forget, no await
   516→        }
   517→        const draft = this.draftManager.getOrCreate(sessionId, threadId);
   518→        draft.append(content.text);
   519→        this.draftManager.appendText(sessionId, content.text);
   520→        break;
   521→      }
   522→
   523→      case "tool_call": {
   524→        const tracker = this.getOrCreateTracker(sessionId, threadId);
   525→        await tracker.onToolCall();
   526→        await this.draftManager.finalize(sessionId, this.assistantSession?.id);
   527→        const meta = content.metadata as never as {
   528→          id: string;
   529→          name: string;
   530→          kind?: string;
   531→          status?: string;
   532→          content?: unknown;
   533→          viewerLinks?: { file?: string; diff?: string };
   534→        };
   535→        await this.toolTracker.trackNewCall(sessionId, threadId, {
   536→          ...meta,
   537→          viewerFilePath: (content.metadata as any)?.viewerFilePath,
   538→        });
   539→        break;
   540→      }
   541→
   542→      case "tool_update": {
   543→        const meta = content.metadata as never as {
   544→          id: string;
   545→          name: string;
   546→          kind?: string;
   547→          status: string;
   548→          content?: unknown;
   549→          viewerLinks?: { file?: string; diff?: string };
   550→        };
   551→        await this.toolTracker.updateCall(sessionId, {
   552→          ...meta,
   553→          viewerFilePath: (content.metadata as any)?.viewerFilePath,
   554→        });
   555→        break;
   556→      }
   557→
   558→      case "plan": {
   559→        const meta = content.metadata as never as {
   560→          entries: Array<{ content: string; status: string; priority: string }>;
   561→        };
   562→        const tracker = this.getOrCreateTracker(sessionId, threadId);
   563→        await tracker.onPlan(
   564→          meta.entries.map(e => ({
   565→            content: e.content,
   566→            status: e.status as 'pending' | 'in_progress' | 'completed',
   567→            priority: (e.priority ?? 'medium') as 'high' | 'medium' | 'low',
   568→          })),
   569→        );
   570→        break;
   571→      }
   572→
   573→      case "usage": {
   574→        const meta = content.metadata as never as {
   575→          tokensUsed?: number;
   576→          contextSize?: number;
   577→        };
   578→        await this.draftManager.finalize(sessionId, this.assistantSession?.id);
   579→        const tracker = this.getOrCreateTracker(sessionId, threadId);
   580→        await tracker.sendUsage(meta);
   581→
   582→        // Notify the Notifications topic that a prompt has completed
   583→        if (this.notificationTopicId && sessionId !== this.assistantSession?.id) {
   584→          const sess = this.core.sessionManager.getSession(sessionId);
   585→          const sessionName = sess?.name || 'Session';
   586→          const chatIdStr = String(this.telegramConfig.chatId);
   587→          const numericId = chatIdStr.startsWith('-100') ? chatIdStr.slice(4) : chatIdStr.replace('-', '');
   588→          const usageMsgId = tracker.getUsageMsgId();
   589→          const deepLink = `https://t.me/c/${numericId}/${usageMsgId ?? threadId}`;
   590→          const text = `✅ <b>${escapeHtml(sessionName)}</b>\nTask completed.\n\n<a href="${deepLink}">→ Go to topic</a>`;
   591→          this.sendQueue.enqueue(() =>
   592→            this.bot.api.sendMessage(this.telegramConfig.chatId, text, {
   593→              message_thread_id: this.notificationTopicId,
   594→              parse_mode: 'HTML',
   595→              disable_notification: false,
   596→            }),
   597→          ).catch(() => {});
   598→        }
   599→        break;
   600→      }
   601→
   602→      case "attachment": {
   603→        if (!content.attachment) break;
   604→        const { attachment } = content;
   605→
   606→        // Telegram bot API upload limit: 50MB
   607→        if (attachment.size > 50 * 1024 * 1024) {
   608→          log.warn({ sessionId, fileName: attachment.fileName, size: attachment.size }, "File too large for Telegram (>50MB)");
   609→          await this.sendQueue.enqueue(() =>
   610→            this.bot.api.sendMessage(
   611→              this.telegramConfig.chatId,
   612→              `⚠️ File too large to send (${Math.round(attachment.size / 1024 / 1024)}MB): ${escapeHtml(attachment.fileName)}`,
   613→              { message_thread_id: threadId, parse_mode: "HTML" },
   614→            ),
   615→          );
   616→          break;
   617→        }
   618→
   619→        try {
   620→          const inputFile = new InputFile(attachment.filePath);
   621→          if (attachment.type === "image") {
   622→            await this.sendQueue.enqueue(() =>
   623→              this.bot.api.sendPhoto(this.telegramConfig.chatId, inputFile, {
   624→                message_thread_id: threadId,
   625→              }),
   626→            );
   627→          } else if (attachment.type === "audio") {
   628→            await this.sendQueue.enqueue(() =>
   629→              this.bot.api.sendVoice(this.telegramConfig.chatId, inputFile, {
   630→                message_thread_id: threadId,
   631→              }),
   632→            );
   633→          } else {
   634→            await this.sendQueue.enqueue(() =>
   635→              this.bot.api.sendDocument(this.telegramConfig.chatId, inputFile, {
   636→                message_thread_id: threadId,
   637→              }),
   638→            );
   639→          }
   640→        } catch (err) {
   641→          log.error({ err, sessionId, fileName: attachment.fileName }, "Failed to send attachment");
   642→        }
   643→        break;
   644→      }
   645→
   646→      case "session_end": {
   647→        await this.draftManager.finalize(sessionId, this.assistantSession?.id);
   648→        this.draftManager.cleanup(sessionId);
   649→        this.toolTracker.cleanup(sessionId);
   650→        await this.skillManager.cleanup(sessionId);
   651→        const tracker = this.sessionTrackers.get(sessionId);
   652→        if (tracker) {
   653→          await tracker.onComplete();
   654→          tracker.destroy();
   655→          this.sessionTrackers.delete(sessionId);
   656→        } else {
   657→          await this.sendQueue.enqueue(() =>
   658→            this.bot.api.sendMessage(
   659→              this.telegramConfig.chatId,
   660→              `✅ <b>Done</b>`,
   661→              {
   662→                message_thread_id: threadId,
   663→                parse_mode: "HTML",
   664→                disable_notification: true,
   665→              },
   666→            ),
   667→          );
   668→        }
   669→        break;
   670→      }
   671→
   672→      case "error": {
   673→        await this.draftManager.finalize(sessionId, this.assistantSession?.id);
   674→        const tracker = this.sessionTrackers.get(sessionId);
   675→        if (tracker) {
   676→          tracker.destroy();
   677→          this.sessionTrackers.delete(sessionId);
   678→        }
   679→        await this.sendQueue.enqueue(() =>
   680→          this.bot.api.sendMessage(
   681→            this.telegramConfig.chatId,
   682→            `❌ <b>Error:</b> ${escapeHtml(content.text)}`,
   683→            {
   684→              message_thread_id: threadId,
   685→              parse_mode: "HTML",
   686→              disable_notification: true,
   687→            },
   688→          ),
   689→        );
   690→        break;
   691→      }
   692→    }
   693→  }
