   695→  async sendPermissionRequest(
   696→    sessionId: string,
   697→    request: PermissionRequest,
   698→  ): Promise<void> {
   699→    log.info({ sessionId, requestId: request.id }, "Permission request sent");
   700→    const session = this.core.sessionManager.getSession(sessionId);
   701→    if (!session) return;
   702→
   703→    // Auto-approve openacp CLI commands
   704→    if (request.description.includes("openacp")) {
   705→      const allowOption = request.options.find((o) => o.isAllow);
   706→      if (allowOption && session.permissionGate.requestId === request.id) {
   707→        log.info({ sessionId, requestId: request.id }, "Auto-approving openacp command");
   708→        session.permissionGate.resolve(allowOption.id);
   709→      }
   710→      return;
   711→    }
   712→
   713→    // Dangerous mode: auto-approve
   714→    if (session.dangerousMode) {
   715→      const allowOption = request.options.find((o) => o.isAllow);
   716→      if (allowOption && session.permissionGate.requestId === request.id) {
   717→        log.info({ sessionId, requestId: request.id, optionId: allowOption.id }, "Dangerous mode: auto-approving permission");
   718→        session.permissionGate.resolve(allowOption.id);
   719→      }
   720→      return;
   721→    }
   722→
   723→    await this.sendQueue.enqueue(() =>
   724→      this.permissionHandler.sendPermissionRequest(session, request),
   725→    );
   726→  }
   727→
   728→  async sendNotification(notification: NotificationMessage): Promise<void> {
   729→    if (notification.sessionId === this.assistantSession?.id) return;
   730→
   731→    log.info(
   732→      { sessionId: notification.sessionId, type: notification.type },
   733→      "Notification sent",
   734→    );
   735→    if (!this.notificationTopicId) return;
   736→    const emoji: Record<string, string> = {
   737→      completed: "✅",
   738→      error: "❌",
   739→      permission: "🔐",
   740→      input_required: "💬",
   741→    };
   742→    let text = `${emoji[notification.type] || "ℹ️"} <b>${escapeHtml(notification.sessionName || "New session")}</b>\n`;
   743→    text += escapeHtml(notification.summary);
   744→
   745→    const deepLink = notification.deepLink ?? (() => {
   746→      const session = this.core.sessionManager.getSession(notification.sessionId);
   747→      const threadId = session?.threadId;
   748→      if (!threadId) return undefined;
   749→      const chatIdStr = String(this.telegramConfig.chatId);
   750→      const numericId = chatIdStr.startsWith("-100") ? chatIdStr.slice(4) : chatIdStr.replace("-", "");
   751→      return `https://t.me/c/${numericId}/${threadId}`;
   752→    })();
   753→
   754→    if (deepLink) {
   755→      text += `\n\n<a href="${deepLink}">→ Go to topic</a>`;
   756→    }
   757→    await this.sendQueue.enqueue(() =>
   758→      this.bot.api.sendMessage(this.telegramConfig.chatId, text, {
   759→        message_thread_id: this.notificationTopicId,
   760→        parse_mode: "HTML",
   761→        disable_notification: false,
   762→      }),
   763→    );
   764→  }
