   785→  async deleteSessionThread(sessionId: string): Promise<void> {
   786→    const record = this.core.sessionManager.getSessionRecord(sessionId);
   787→    const platform = record?.platform as import("../../core/types.js").TelegramPlatformData | undefined;
   788→    const topicId = platform?.topicId;
