    10→// Valid state transitions: from → Set<to>
    11→const VALID_TRANSITIONS: Record<SessionStatus, Set<SessionStatus>> = {
    12→  initializing: new Set(["active", "error"]),
    13→  active: new Set(["error", "finished", "cancelled"]),
    14→  error: new Set(["active"]),
    15→  cancelled: new Set(["active"]),
