    24→/** Find the nearest ancestor directory containing package.json */
    25→function findPackageRoot(startDir: string): string {
    26→  let dir = startDir;
    27→  while (dir !== path.dirname(dir)) {
    28→    if (fs.existsSync(path.join(dir, "package.json"))) {
    29→      return dir;
    30→    }
    31→    dir = path.dirname(dir);
    32→  }
    33→  return startDir;
    34→}
