816→  private async downloadTelegramFile(fileId: string): Promise<{ buffer: Buffer; filePath: string } | null> {
817→    try {
818→      const file = await this.bot.api.getFile(fileId);
819→      if (!file.file_path) return null;
820→      const url = `https://api.telegram.org/file/bot${this.telegramConfig.botToken}/${file.file_path}`;
821→      const response = await fetch(url);
822→      if (!response.ok) return null;
823→      const buffer = Buffer.from(await response.arrayBuffer());
824→      return { buffer, filePath: file.file_path };
825→    } catch (err) {
826→      log.error({ err }, "Failed to download file from Telegram");
827→      return null;
828→    }
829→  }
