440→      const doc = ctx.message.document;
441→      await this.handleIncomingMedia(
442→        threadId, ctx.from.id, doc.file_id,
443→        doc.file_name || "document", doc.mime_type || "application/octet-stream",
444→        ctx.message.caption || undefined,
445→      );
446→    });
447→
448→    this.bot.on("message:voice", async (ctx) => {
449→      const threadId = ctx.message.message_thread_id;
450→      if (!threadId || threadId === this.notificationTopicId) return;
451→
452→      const voice = ctx.message.voice;
453→      await this.handleIncomingMedia(
