819→      if (!file.file_path) return null;
820→      const url = `https://api.telegram.org/file/bot${this.telegramConfig.botToken}/${file.file_path}`;
821→      const response = await fetch(url);
822→      if (!response.ok) return null;
823→      const buffer = Buffer.from(await response.arrayBuffer());
