 3→export type QueueItemType = 'text' | 'other'
 4→
 5→interface QueueItem<T = unknown> {
 6→  fn: () => Promise<T>
 7→  type: QueueItemType
 8→  key?: string
 9→  resolve: (value: T | undefined) => void
10→  reject: (err: unknown) => void
11→}
12→
13→export class DiscordSendQueue {
14→  private items: QueueItem[] = []
15→  private processing = false
16→  private lastExec = 0
17→  private minInterval: number
18→
19→  constructor(minInterval = 1000) {
20→    this.minInterval = minInterval
21→  }
22→
23→  enqueue<T>(
24→    fn: () => Promise<T>,
25→    opts: { type: 'text' | 'other'; key?: string },
26→  ): Promise<T | undefined> {
27→    const type = opts.type
28→    const key = opts.key
29→
30→    return new Promise<T | undefined>((resolve, reject) => {
31→      if (type === 'text' && key) {
32→        const idx = this.items.findIndex(
33→          (item) => item.type === 'text' && item.key === key,
34→        )
35→        if (idx !== -1) {
36→          // Resolve old pending item with undefined (dedup: replace with newer)
37→          this.items[idx].resolve(undefined)
38→          this.items[idx] = { fn, type, key, resolve, reject } as QueueItem
39→          this.scheduleProcess()
40→          return
41→        }
42→      }
43→
44→      this.items.push({ fn, type, key, resolve, reject } as QueueItem)
45→      this.scheduleProcess()
46→    })
47→  }
48→
49→  onRateLimited(): void {
50→    log.warn('[DiscordSendQueue] Rate limited — dropping queued text items')
51→    const remaining: QueueItem[] = []
52→    for (const item of this.items) {
53→      if (item.type === 'text') {
54→        item.resolve(undefined)
55→      } else {
56→        remaining.push(item)
57→      }
58→    }
59→    this.items = remaining
60→  }
61→
62→  private scheduleProcess(): void {
63→    if (this.processing) return
64→    if (this.items.length === 0) return
65→
66→    const elapsed = Date.now() - this.lastExec
67→    const delay = Math.max(0, this.minInterval - elapsed)
68→
69→    this.processing = true
70→    setTimeout(() => void this.processNext(), delay)
71→  }
72→
73→  private async processNext(): Promise<void> {
74→    const item = this.items.shift()
75→    if (!item) {
76→      this.processing = false
77→      return
78→    }
79→
80→    try {
81→      const result = await item.fn()
82→      item.resolve(result)
83→    } catch (err) {
84→      item.reject(err)
85→    } finally {
86→      this.lastExec = Date.now()
87→      this.processing = false
88→      this.scheduleProcess()
89→    }
90→  }
91→}
