134→export function createSessionLogger(sessionId: string, parentLogger: Logger): Logger {
135→  const sessionLogDir = logDir ? path.join(logDir, 'sessions') : undefined
136→  if (!sessionLogDir) {
137→    return parentLogger.child({ sessionId })
138→  }
139→
140→  try {
141→    const sessionLogPath = path.join(sessionLogDir, `${sessionId}.log`)
142→    const dest = pino.destination(sessionLogPath)
143→    const sessionFileLogger = pino({ level: parentLogger.level }, dest).child({ sessionId })
144→
145→    // Create a logger that writes to both parent (combined) and session file
146→    const combinedChild = parentLogger.child({ sessionId })
147→    const originalInfo = combinedChild.info.bind(combinedChild)
148→    const originalWarn = combinedChild.warn.bind(combinedChild)
149→    const originalError = combinedChild.error.bind(combinedChild)
150→    const originalDebug = combinedChild.debug.bind(combinedChild)
151→    const originalFatal = combinedChild.fatal.bind(combinedChild)
152→
153→    // Proxy log methods to write to both destinations
154→    combinedChild.info = ((objOrMsg: any, ...rest: any[]) => {
155→      sessionFileLogger.info(objOrMsg, ...rest)
156→      return originalInfo(objOrMsg, ...rest)
157→    }) as any
158→    combinedChild.warn = ((objOrMsg: any, ...rest: any[]) => {
159→      sessionFileLogger.warn(objOrMsg, ...rest)
160→      return originalWarn(objOrMsg, ...rest)
161→    }) as any
162→    combinedChild.error = ((objOrMsg: any, ...rest: any[]) => {
163→      sessionFileLogger.error(objOrMsg, ...rest)
164→      return originalError(objOrMsg, ...rest)
165→    }) as any
166→    combinedChild.debug = ((objOrMsg: any, ...rest: any[]) => {
167→      sessionFileLogger.debug(objOrMsg, ...rest)
168→      return originalDebug(objOrMsg, ...rest)
169→    }) as any
170→    combinedChild.fatal = ((objOrMsg: any, ...rest: any[]) => {
171→      sessionFileLogger.fatal(objOrMsg, ...rest)
172→      return originalFatal(objOrMsg, ...rest)
173→    }) as any
174→
175→    // Store dest for cleanup
176→    ;(combinedChild as any).__sessionDest = dest
177→
178→    return combinedChild
179→  } catch (err) {
