async prompt(text: string, attachments?: Attachment[]): Promise<PromptResponse> {
  const contentBlocks: Array<Record<string, unknown>> = [{ type: "text", text }];

  for (const att of attachments ?? []) {
    const tooLarge = att.size > 10 * 1024 * 1024; // 10MB base64 guard

    if (att.type === "image" && this.promptCapabilities?.image && !tooLarge) {
      const data = await fs.promises.readFile(att.filePath);
      contentBlocks.push({ type: "image", data: data.toString("base64"), mimeType: att.mimeType });
    } else if (att.type === "audio" && this.promptCapabilities?.audio && !tooLarge) {
      const data = await fs.promises.readFile(att.filePath);
      contentBlocks.push({ type: "audio", data: data.toString("base64"), mimeType: att.mimeType });
    } else {
      // Fallback: append file path to text so agent can read from disk
      if ((att.type === "image" || att.type === "audio") && !tooLarge) {
        log.debug(
          { type: att.type, capabilities: this.promptCapabilities ?? {} },
          "Agent does not support %s content, falling back to file path",
          att.type,
        );
      }
      (contentBlocks[0] as { text: string }).text += `\n\n[Attached file: ${att.filePath}]`;
    }
  }

  return this.connection.prompt({
    sessionId: this.sessionId,
    prompt: contentBlocks as any,
  });
}

async cancel(): Promise<void> {
  await this.connection.cancel({ sessionId: this.sessionId });
}

async destroy(): Promise<void> {
  // Cleanup terminals
  for (const [, t] of this.terminals) {
    t.process.kill("SIGKILL");
  }
  this.terminals.clear();

  // Kill agent subprocess
  this.child.kill("SIGTERM");
  setTimeout(() => {
    if (!this.child.killed) this.child.kill("SIGKILL");
  }, 10_000);

private setupMessageHandler(): void {
  this.client.on('messageCreate', async (message) => {
    try {
      // Ignore bots and self
      if (message.author.bot) return

      // Ignore DMs
      if (!message.guild) return

      // Ignore messages from the wrong guild
      if (message.guild.id !== this.guild.id) return

      // Only process messages in threads
      if (!message.channel.isThread()) return

      const threadId = message.channel.id
      const userId = message.author.id
      let text = message.content

      // Ignore messages with no text and no attachments
      if (!text && message.attachments.size === 0) return

      // Resolve sessionId for file storage (fallback to "unknown" for new sessions)
      const sessionId =
        this.core.sessionManager.getSessionByThread('discord', threadId)?.id ?? 'unknown'

      // Process attachments
      const attachments = await this.processIncomingAttachments(message, sessionId)

      // Generate fallback text if message has attachments but no text
      if (!text && attachments.length > 0) {
        text = buildFallbackText(attachments)
      }

      // If all attachment downloads failed and no text, notify user
      if (!text && attachments.length === 0 && message.attachments.size > 0) {
        try {
          await message.reply('Failed to process attachment(s)')
        } catch { /* best effort */ }
        return
      }

      // Route assistant thread messages to assistant
      if (
        this.discordConfig.assistantThreadId &&
        threadId === this.discordConfig.assistantThreadId
      ) {
        if (this.assistantSession && text) {
          await this.assistantSession.enqueuePrompt(text, attachments.length > 0 ? attachments : undefined)
        }
        return
      }

      // Route to core for session dispatch
      await this.core.handleMessage({
        channelId: 'discord',
        threadId,
        userId,
        text,
        ...(attachments.length > 0 ? { attachments } : {}),
      })
    } catch (err) {
      log.error({ err }, '[DiscordAdapter] messageCreate handler error')
    }
  })
}

