154→async function detectChatId(token: string): Promise<number> {
155→  // Clear old updates
156→  let lastUpdateId = 0;
157→  try {
158→    const clearRes = await fetch(
159→      `https://api.telegram.org/bot${token}/getUpdates?offset=-1`,
160→    );
161→    const clearData = (await clearRes.json()) as {
162→      ok: boolean;
163→      result?: Array<{ update_id: number }>;
164→    };
165→    if (clearData.ok && clearData.result?.length) {
166→      lastUpdateId = clearData.result[clearData.result.length - 1].update_id;
167→    }
168→  } catch {
169→    // ignore
170→  }
171→
172→  console.log("");
173→  console.log(`  ${c.bold}If you don't have a supergroup yet:${c.reset}`);
174→  console.log(dim("  1. Open Telegram → New Group → add your bot"));
175→  console.log(dim("  2. Group Settings → convert to Supergroup"));
176→  console.log(dim("  3. Enable Topics in group settings"));
177→  console.log("");
178→  console.log(`  ${c.bold}Then send "hi" in the group.${c.reset}`);
179→  console.log(
180→    dim(
181→      `  Listening... press ${c.reset}${c.yellow}m${c.reset}${c.dim} to enter ID manually`,
182→    ),
183→  );
184→  console.log("");
185→
186→  const MAX_ATTEMPTS = 120;
187→  const POLL_INTERVAL = 1000;
188→
189→  // Listen for 'm' keypress to switch to manual
190→  let cancelled = false;
191→  const onKeypress = (data: Buffer) => {
192→    const key = data.toString();
193→    if (key === "m" || key === "M") {
194→      cancelled = true;
195→    }
196→  };
197→  if (process.stdin.isTTY) {
198→    process.stdin.setRawMode(true);
199→    process.stdin.resume();
200→    process.stdin.on("data", onKeypress);
201→  }
202→
203→  const cleanup = () => {
204→    if (process.stdin.isTTY) {
205→      process.stdin.removeListener("data", onKeypress);
206→      process.stdin.setRawMode(false);
207→      process.stdin.pause();
208→    }
209→  };
210→
211→  try {
212→    for (let i = 0; i < MAX_ATTEMPTS; i++) {
213→      if (cancelled) {
214→        cleanup();
215→        return promptManualChatId();
216→      }
217→
218→      try {
219→        const offset = lastUpdateId ? lastUpdateId + 1 : 0;
220→        const res = await fetch(
221→          `https://api.telegram.org/bot${token}/getUpdates?offset=${offset}&timeout=1`,
222→        );
223→        const data = (await res.json()) as {
224→          ok: boolean;
225→          result?: Array<{
226→            update_id: number;
227→            message?: {
228→              chat: { id: number; title?: string; type: string };
229→            };
230→            my_chat_member?: {
231→              chat: { id: number; title?: string; type: string };
232→            };
233→          }>;
234→        };
235→
236→        if (!data.ok || !data.result?.length) {
237→          await new Promise((r) => setTimeout(r, POLL_INTERVAL));
238→          continue;
239→        }
240→
241→        const groups = new Map<number, string>();
242→        for (const update of data.result) {
243→          lastUpdateId = update.update_id;
244→          const chat = update.message?.chat ?? update.my_chat_member?.chat;
245→          if (chat && (chat.type === "supergroup" || chat.type === "group")) {
246→            groups.set(chat.id, chat.title ?? String(chat.id));
247→          }
248→        }
249→
250→        if (groups.size === 1) {
251→          const [id, title] = [...groups.entries()][0];
252→          console.log(
253→            ok(`Group detected: ${c.bold}${title}${c.reset}${c.green} (${id})`),
254→          );
255→          cleanup();
256→          return id;
257→        }
258→
259→        if (groups.size > 1) {
260→          cleanup();
261→          const choices = [...groups.entries()].map(([id, title]) => ({
262→            name: `${title} (${id})`,
263→            value: id,
264→          }));
265→          return select({
266→            message: "Multiple groups found. Pick one:",
267→            choices,
268→          });
269→        }
270→      } catch {
271→        // Network error, retry
272→      }
273→      await new Promise((r) => setTimeout(r, POLL_INTERVAL));
274→    }
275→
276→    console.log(warn("Timed out waiting for messages."));
277→    cleanup();
278→    return promptManualChatId();
279→  } catch (err) {
280→    cleanup();
281→    throw err;
282→  }
283→}
