294→export async function detectAgents(): Promise<
295→  Array<{ name: string; command: string }>
296→> {
297→  const found: Array<{ name: string; command: string }> = [];
298→  for (const agent of KNOWN_AGENTS) {
299→    // Find all available commands for this agent (PATH + node_modules/.bin)
300→    const available: string[] = [];
301→    for (const cmd of agent.commands) {
302→      if (commandExists(cmd)) {
303→        available.push(cmd);
304→      }
305→    }
306→    if (available.length > 0) {
307→      // Prefer claude-agent-acp over claude/claude-code (priority order)
308→      found.push({ name: agent.name, command: available[0] });
309→    }
310→  }
311→  return found;
312→}
