405→export async function validateDiscordToken(token: string): Promise<
406→  | { ok: true; username: string; id: string }
407→  | { ok: false; error: string }
408→> {
409→  try {
410→    const res = await fetch("https://discord.com/api/v10/users/@me", {
411→      headers: { Authorization: `Bot ${token}` },
412→    });
413→    if (res.status === 200) {
414→      const data = (await res.json()) as { username: string; id: string };
415→      return { ok: true, username: data.username, id: data.id };
416→    }
417→    if (res.status === 401) {
418→      return { ok: false, error: "Token rejected by Discord (401 Unauthorized)" };
419→    }
420→    return { ok: false, error: `Discord API returned ${res.status}` };
421→  } catch (err) {
422→    return { ok: false, error: (err as Error).message };
423→  }
424→}
