633→export async function runSetup(configManager: ConfigManager): Promise<boolean> {
634→  printWelcomeBanner();
635→
636→  try {
637→    const { select: selectChannel } = await import("@inquirer/prompts");
638→    const channelChoice = await selectChannel({
639→      message: 'Which messaging platform do you want to use?',
640→      choices: [
