642→        { name: 'Discord', value: 'discord' },
643→        { name: 'Both', value: 'both' },
644→      ],
645→    });
646→
647→    let telegram: Config["channels"][string] | undefined;
648→    let discord: DiscordChannelConfig | undefined;
649→
650→    // Calculate total steps dynamically: channel(s) + workspace + run mode
651→    const channelSteps = channelChoice === 'both' ? 2 : 1;
652→    const totalSteps = channelSteps + 2; // + workspace + run mode
653→
654→    let currentStep = 0;
655→
656→    if (channelChoice === 'telegram' || channelChoice === 'both') {
657→      currentStep++;
658→      telegram = await setupTelegram(currentStep, totalSteps);
659→    }
660→    if (channelChoice === 'discord' || channelChoice === 'both') {
661→      currentStep++;
662→      discord = await setupDiscord();
