 1→import type { DoctorCheck, CheckResult } from "../types.js";
 2→
 3→// Discord bot tokens are base64-encoded and follow a recognizable pattern:
 4→// <user_id>.<timestamp>.<hmac> — the user_id part is a base64-encoded snowflake
 5→const BOT_TOKEN_REGEX = /^[A-Za-z0-9_-]{24,28}\.[A-Za-z0-9_-]{6,7}\.[A-Za-z0-9_-]{27,}$/;
 6→
 7→export const discordCheck: DoctorCheck = {
 8→  name: "Discord",
 9→  order: 3.5,
10→  async run(ctx) {
11→    const results: CheckResult[] = [];
12→
13→    if (!ctx.config) {
14→      results.push({ status: "fail", message: "Cannot check Discord — config not loaded" });
15→      return results;
16→    }
17→
18→    const discordConfig = (ctx.config.channels as Record<string, unknown>).discord as Record<string, unknown> | undefined;
19→    if (!discordConfig || !discordConfig.enabled) {
20→      results.push({ status: "pass", message: "Discord not enabled (skipped)" });
21→      return results;
22→    }
23→
24→    // Check 1: Bot token format/presence
25→    const botToken = discordConfig.botToken as string | undefined;
26→    if (!botToken || !BOT_TOKEN_REGEX.test(botToken)) {
27→      results.push({ status: "fail", message: "Discord bot token format invalid or missing" });
28→      return results;
29→    }
30→    results.push({ status: "pass", message: "Discord bot token format valid" });
31→
32→    // Check 2: Token validity via GET https://discord.com/api/v10/users/@me
33→    let botUsername: string | undefined;
34→    try {
35→      const res = await fetch("https://discord.com/api/v10/users/@me", {
36→        headers: { Authorization: `Bot ${botToken}` },
37→      });
38→      if (res.status === 200) {
39→        const data = (await res.json()) as { username: string; id: string };
40→        botUsername = data.username;
41→        results.push({ status: "pass", message: `Bot token valid (@${data.username}, id: ${data.id})` });
42→      } else if (res.status === 401) {
43→        results.push({ status: "fail", message: "Bot token rejected by Discord (401 Unauthorized)" });
44→        return results;
45→      } else {
46→        const text = await res.text();
47→        results.push({ status: "fail", message: `Discord API error ${res.status}: ${text.slice(0, 100)}` });
48→        return results;
49→      }
50→    } catch (err) {
51→      results.push({ status: "fail", message: `Cannot reach Discord API: ${err instanceof Error ? err.message : String(err)}` });
52→      return results;
53→    }
54→
55→    // Check 3: Guild access via GET https://discord.com/api/v10/guilds/{guildId}
56→    const guildId = discordConfig.guildId as string | undefined;
57→    if (!guildId) {
58→      results.push({ status: "fail", message: "Guild ID not configured" });
59→      return results;
60→    }
61→
62→    try {
63→      const res = await fetch(`https://discord.com/api/v10/guilds/${guildId}`, {
64→        headers: { Authorization: `Bot ${botToken}` },
65→      });
66→      if (res.status === 200) {
67→        const data = (await res.json()) as { name: string; id: string };
68→        results.push({ status: "pass", message: `Bot has access to guild "${data.name}" (id: ${data.id})` });
69→      } else if (res.status === 403) {
70→        results.push({
71→          status: "fail",
72→          message: `Bot (${botUsername ?? "unknown"}) is not a member of guild ${guildId} or lacks access. Invite the bot to your server.`,
73→        });
74→      } else if (res.status === 404) {
75→        results.push({ status: "fail", message: `Guild ${guildId} not found — check the guild ID` });
76→      } else {
77→        const text = await res.text();
78→        results.push({ status: "fail", message: `Guild check error ${res.status}: ${text.slice(0, 100)}` });
79→      }
80→    } catch (err) {
81→      results.push({ status: "fail", message: `Cannot validate guild: ${err instanceof Error ? err.message : String(err)}` });
82→    }
83→
84→    return results;
85→  },
86→};
