176→// ─── buildDeepLink ────────────────────────────────────────────────────────────
177→
178→/**
179→ * Builds a Discord deep link URL to a channel/thread, optionally to a specific message.
180→ */
181→export function buildDeepLink(
182→  guildId: string,
183→  channelId: string,
184→  messageId?: string,
185→): string {
186→  const base = `https://discord.com/channels/${guildId}/${channelId}`
187→  return messageId ? `${base}/${messageId}` : base
188→}
